import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type DollarTurnWalkProps = Record<string, any>;

const DollarTurnWalk: React.FC<DollarTurnWalkProps> = ({
  backgroundColor = "#1A1A1A",
  transparentBackground = false,
  durationInSeconds = 8,
  wallColor = "#2A2A35",
  floorColor = "#15151D",
  doorColor = "#E63946",
  dollarColor = "#2A9D8F",
  doorLabel = "BETH",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparent background logic safely
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timeline Math based on duration
  const totalFrames = durationInSeconds * fps;
  const arriveFrame = Math.round(totalFrames * 0.35);
  const doorShutStart = arriveFrame - 15;
  const doorShutEnd = arriveFrame + 10;
  const turnStart = doorShutEnd + 20;
  const turnEnd = turnStart + 12;
  const exitEnd = Math.round(totalFrames * 0.9);

  // Position & Movement Interpolations
  const dollarStartX = width * 1.2;
  const dollarStopX = width * 0.32;

  const dollarX = interpolate(
    frame,
    [0, arriveFrame, turnEnd, exitEnd],
    [dollarStartX, dollarStopX, dollarStopX, dollarStartX],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Walk Phase (accumulates continuously based on timeline segments to ensure cyclic math)
  const enterSteps = 12; // 12 * PI = 6 full steps
  const enterPhaseMax = enterSteps * Math.PI;

  const walkPhase = interpolate(
    frame,
    [0, arriveFrame, turnEnd, exitEnd],
    [0, enterPhaseMax, enterPhaseMax, enterPhaseMax * 2],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Bobbing and Leg Rotations derived purely from the walkPhase
  const bob = Math.abs(Math.sin(walkPhase)) * 25;
  const leftLegRot = Math.sin(walkPhase) * 35;
  const rightLegRot = Math.sin(walkPhase + Math.PI) * 35;

  // Character Turn (ScaleX)
  const direction = interpolate(
    frame,
    [turnStart, turnEnd],
    [1, -1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.inOut(Easing.quad) }
  );

  // Door Swing Animation
  const doorRotY = interpolate(
    frame,
    [0, doorShutStart, doorShutEnd],
    [-85, -85, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.in(Easing.quad) }
  );

  // Layout Constants
  const floorLevel = height * 0.8;
  const doorWidth = width * 0.12;
  const doorHeight = height * 0.45;
  const dollarWidth = 300;
  const dollarHeight = 150;
  const legLength = 120;
  const characterTotalHeight = dollarHeight + legLength;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      {/* Wall */}
      <div style={{ position: "absolute", inset: 0, backgroundColor: wallColor, transition: "none" }} />
      
      {/* Baseboard */}
      <div style={{ position: "absolute", bottom: height * 0.2, width: "100%", height: 20, backgroundColor: "rgba(0,0,0,0.2)", transition: "none" }} />
      
      {/* Floor */}
      <div style={{ position: "absolute", bottom: 0, width: "100%", height: height * 0.2, backgroundColor: floorColor, transition: "none" }} />

      {/* Door Assembly */}
      <div style={{
        position: "absolute",
        left: width * 0.15,
        bottom: height * 0.2,
        width: doorWidth,
        height: doorHeight,
        transition: "none",
      }}>
        {/* Sign Above Door */}
        <div style={{
          position: "absolute",
          top: -100,
          left: -20,
          right: -20,
          height: 70,
          backgroundColor: "#1A1A1A",
          border: "4px solid #333",
          borderRadius: 8,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          boxShadow: "0 10px 30px rgba(0,0,0,0.4)",
          transition: "none",
        }}>
          <span style={{
            color: "#ffffff",
            fontSize: 40,
            fontWeight: "bold",
            fontFamily: robotoMonoFamily,
            letterSpacing: 4,
            transition: "none",
          }}>
            {doorLabel}
          </span>
        </div>

        {/* Door Frame (Outer) */}
        <div style={{
          position: "absolute",
          inset: "-15px -15px 0 -15px",
          backgroundColor: "#1F1F27",
          borderTopLeftRadius: 10,
          borderTopRightRadius: 10,
          boxShadow: "10px 10px 30px rgba(0,0,0,0.3)",
          transition: "none",
        }} />

        {/* The Swinging Door inside Perspective Container */}
        <div style={{
          position: "absolute",
          inset: 0,
          backgroundColor: "#050505", // The dark room behind the door
          perspective: "1500px",
          transition: "none",
        }}>
          <div style={{
            width: "100%",
            height: "100%",
            backgroundColor: doorColor,
            transformOrigin: "left",
            transform: `rotateY(${doorRotY}deg)`,
            border: "3px solid rgba(0,0,0,0.5)",
            display: "flex",
            alignItems: "center",
            justifyContent: "flex-end",
            boxShadow: "inset -10px 0 30px rgba(0,0,0,0.3)",
            transition: "none",
          }}>
            {/* Door Knob */}
            <div style={{
              width: 18,
              height: 18,
              borderRadius: "50%",
              backgroundColor: "#E0E0E0",
              marginRight: 20,
              boxShadow: "2px 2px 10px rgba(0,0,0,0.5)",
              transition: "none",
            }} />
          </div>
        </div>
      </div>

      {/* Dollar Character Container */}
      <div style={{
        position: "absolute",
        left: dollarX,
        top: floorLevel - characterTotalHeight,
        width: dollarWidth,
        height: characterTotalHeight,
        transition: "none",
      }}>
        {/* Floor Shadow */}
        <div style={{
          position: "absolute",
          bottom: -10,
          left: (dollarWidth / 2) - 60,
          width: 120,
          height: 15,
          backgroundColor: "rgba(0,0,0,0.5)",
          borderRadius: "50%",
          transform: `scale(${1 - bob / 60})`,
          filter: "blur(6px)",
          transition: "none",
        }} />

        {/* Bobbing & Turning Body */}
        <div style={{
          width: "100%",
          height: "100%",
          transformOrigin: "center center",
          transform: `scaleX(${direction}) translateY(${-bob}px)`,
          transition: "none",
        }}>
          
          {/* Dollar Bill SVG */}
          <svg width={dollarWidth} height={dollarHeight} viewBox="0 0 300 150" style={{ position: "absolute", top: 0, left: 0, zIndex: 10, transition: "none" }}>
            <rect x="5" y="5" width="290" height="140" rx="12" fill={dollarColor} stroke="#ffffff" strokeWidth="6" />
            <rect x="20" y="20" width="260" height="110" rx="4" fill="none" stroke="#ffffff" strokeWidth="2" strokeDasharray="6,6" />
            <ellipse cx="150" cy="75" rx="55" ry="45" fill="none" stroke="#ffffff" strokeWidth="4" />
            <text x="150" y="108" fontSize="95" textAnchor="middle" fontWeight="900" fill="#ffffff" fontFamily={interFamily}>$</text>
            <text x="45" y="45" fontSize="24" textAnchor="middle" fontWeight="bold" fill="#ffffff" fontFamily={interFamily}>1</text>
            <text x="255" y="45" fontSize="24" textAnchor="middle" fontWeight="bold" fill="#ffffff" fontFamily={interFamily}>1</text>
            <text x="45" y="125" fontSize="24" textAnchor="middle" fontWeight="bold" fill="#ffffff" fontFamily={interFamily}>1</text>
            <text x="255" y="125" fontSize="24" textAnchor="middle" fontWeight="bold" fill="#ffffff" fontFamily={interFamily}>1</text>
          </svg>

          {/* Left Leg */}
          <div style={{
            position: "absolute",
            top: dollarHeight - 15,
            left: 90,
            width: 8,
            height: legLength,
            backgroundColor: "#ffffff",
            borderRadius: 4,
            transformOrigin: "top center",
            transform: `rotate(${leftLegRot}deg)`,
            zIndex: 5,
            boxShadow: "2px 0 5px rgba(0,0,0,0.2)",
            transition: "none",
          }}>
            {/* Left Foot */}
            <div style={{
              position: "absolute",
              bottom: 0,
              left: -18,
              width: 26,
              height: 10,
              backgroundColor: "#ffffff",
              borderRadius: 5,
              transition: "none",
            }} />
          </div>

          {/* Right Leg */}
          <div style={{
            position: "absolute",
            top: dollarHeight - 15,
            left: 200,
            width: 8,
            height: legLength,
            backgroundColor: "#ffffff",
            borderRadius: 4,
            transformOrigin: "top center",
            transform: `rotate(${rightLegRot}deg)`,
            zIndex: 5,
            boxShadow: "2px 0 5px rgba(0,0,0,0.2)",
            transition: "none",
          }}>
            {/* Right Foot */}
            <div style={{
              position: "absolute",
              bottom: 0,
              left: -18,
              width: 26,
              height: 10,
              backgroundColor: "#ffffff",
              borderRadius: 5,
              transition: "none",
            }} />
          </div>

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default DollarTurnWalk;